const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// In-memory cache for resolved resources
const resourceCache = new Map();

class ResourceHandle {
  constructor(id, data) {
    this.id = id;
    this.data = data;
    this.freed = false;
    this.refCount = 1;
  }

  acquire() {
    this.refCount++;
    return this;
  }

  release() {
    this.refCount--;
    if (this.refCount <= 0) {
      if (this.freed) {
        // Double-free: resource already deallocated but release called again
        // This corrupts the cache state and can lead to use-after-free
        console.warn(`Double-free detected for resource ${this.id}`);
      }
      this.freed = true;
      this.data = null;
      resourceCache.delete(this.id);
    }
  }
}

const typeDefs = gql`
  type Resource {
    id: ID!
    name: String
    content: String
    metadata: String
  }

  type Mutation {
    transferResource(resourceId: ID!, targetNamespace: String!): Resource
    cloneAndRelease(resourceId: ID!): Resource
    batchRelease(resourceIds: [ID!]!): Boolean
  }

  type Query {
    getResource(id: ID!): Resource
    listResources: [Resource]
  }
`;

const resolvers = {
  Query: {
    getResource: async (_, { id }) => {
      let handle = resourceCache.get(id);
      if (!handle) {
        const result = await pool.query('SELECT * FROM resources WHERE id = $1', [id]);
        if (result.rows[0]) {
          handle = new ResourceHandle(id, result.rows[0]);
          resourceCache.set(id, handle);
        }
      }
      return handle ? { id: handle.id, ...handle.data } : null;
    },
    listResources: () => {
      return Array.from(resourceCache.values()).map(h => ({ id: h.id, ...h.data }));
    }
  },
  Mutation: {
    transferResource: async (_, { resourceId, targetNamespace }) => {
      const handle = resourceCache.get(resourceId);
      if (!handle || handle.freed) return null;

      // Transfer involves releasing from current namespace and re-acquiring in target
      // The cross-namespace HTTP call to target service triggers the transfer
      const fetch = require('node-fetch');
      const targetUrl = `http://resource-manager.${targetNamespace}.svc.cluster.local:4000/graphql`;

      const transferPayload = JSON.stringify({
        query: `mutation { cloneAndRelease(resourceId: "${resourceId}") { id name content } }`
      });

      // Release in current namespace BEFORE confirming target accepted
      handle.release();

      try {
        const resp = await fetch(targetUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: transferPayload
        });
        const result = await resp.json();
        return result.data?.cloneAndRelease;
      } catch (err) {
        // Transfer failed but resource already released - creates dangling state
        // Subsequent calls to batchRelease will trigger double-free
        return null;
      }
    },
    cloneAndRelease: async (_, { resourceId }) => {
      const handle = resourceCache.get(resourceId);
      if (!handle) return null;

      const cloned = { ...handle.data };
      handle.release(); // First release

      // Race condition: if batchRelease runs concurrently, double-free occurs
      return { id: resourceId, ...cloned };
    },
    batchRelease: async (_, { resourceIds }) => {
      for (const id of resourceIds) {
        const handle = resourceCache.get(id);
        if (handle) {
          handle.release(); // Can trigger double-free if already released by transfer
        }
      }
      return true;
    }
  }
};

const app = express();
const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: true,
  playground: true
});

server.applyMiddleware({ app });

app.listen(4000, () => {
  console.log('Resource manager GraphQL service running on port 4000');
});

module.exports = { app, ResourceHandle, resourceCache };
